from typing import Annotated
from fastapi import Depends, FastAPI, Response
from fastapi.testclient import TestClient

app = FastAPI()

def modify_response(response: Response):
    response.headers["X-Custom"] = "custom"
    return response

@app.get("/annotated")
def annotated(response: Annotated[Response, Depends(modify_response)]):
    return {"ok": True}

@app.get("/default")
def default(response: Response = Depends(modify_response)):
    return {"ok": True}

@app.get("/plain")
def plain(response: Response):
    response.headers["X-Plain"] = "yes"
    return {"ok": True}

client = TestClient(app)
for path in ["/annotated", "/default", "/plain"]:
    r = client.get(path)
    print(path, r.status_code, dict(r.headers))
EOF
